const reviewList = document.querySelector(".reviews");
const nextBtn = document.querySelector(".nextbutton");
const backBtn = document.querySelector(".backbutton");
var currentIndex = 0;

nextBtn.addEventListener("click", function() {

  if (currentIndex + 15 < data.length) {
    currentIndex += 15;
    reviewList.innerHTML = "";
    for (var i = currentIndex; i < currentIndex + 15; i++) {
      var customer = data[i];
      reviewList.innerHTML += "<div class='card review-block'><div class='card-body'><img class = 'star-rating' src = " + customer.star_rating + 'stars.png' + "><h5 class='card-title'>" + customer.reviewer + " " + customer.date_reviewed + "</h5><p class='card-text'>" + customer.message + "</p></div></div>";
      location.href = "#";
      location.href = "#section2";
    }
  }
});

backBtn.addEventListener("click", function() {

  if (currentIndex - 15 >= 0) {
    currentIndex -= 15;
    reviewList.innerHTML = "";
    for (var i = currentIndex; i < currentIndex + 15; i++) {
      var customer = data[i];
      reviewList.innerHTML += "<div class='card review-block'><div class='card-body'><img class = 'star-rating' src = " + customer.star_rating + 'stars.png' + "><h5 class='card-title'>" + customer.reviewer + " " + customer.date_reviewed + "</h5><p class='card-text'>" + customer.message + "</p></div></div>";
    }
  }
});

for (var i = currentIndex; i < currentIndex + 15; i++) {
  var customer = data[i];
  reviewList.innerHTML += "<div class='card review-block'><div class='card-body'><img class = 'star-rating' src = " + customer.star_rating + 'stars.png' + "><h5 class='card-title'>" + customer.reviewer + " " + customer.date_reviewed + "</h5><p class='card-text'>" + customer.message + "</p></div></div>";
}
